import requests

headers = {
    'x-api-key': 'YOUR_API_KEY',
    'Content-Type': 'application/json'
}
data = {
    'notification_urls': [
        'mailto:admin@example.com'
    ]
}
response = requests.delete('http://localhost:5000/api/v1/notifications', 
                         headers=headers, json=data)
print(response.status_code)

